INSERT INTO `topics` (`topic_name`, `description`, `difficulty`, `category`, `topic_type`, `source`, `requirements`, `references`, `creator_id`, `selection_count`, `max_students`, `status`, `created_at`, `updated_at`) VALUES 
('基于Vue3的在线教育平台设计与实现', '使用Vue3 + Spring Boot构建完整的在线教育系统，支持视频播放、在线考试、作业提交等功能', 3, 'Web开发', 'engineering', 'teacher', '熟悉Vue3和Spring Boot框架', '[1] Vue.js官方文档 [2] Spring Boot实战', 3, 0, 1, 'available', NOW(), NOW()),
('基于深度学习的图像识别系统', '研究CNN在图像分类中的应用，实现一个可识别多种物体的智能系统', 4, 'AI研究', 'research', 'teacher', '熟悉Python和PyTorch框架', '[1] 深度学习 [2] PyTorch官方教程', 3, 0, 1, 'available', NOW(), NOW()),
('基于区块链的供应链管理系统', '利用区块链技术实现供应链信息的透明化和可追溯性', 5, '区块链', 'engineering', 'teacher', '了解区块链基本原理和智能合约开发', '[1] 区块链技术指南 [2] 以太坊开发文档', 3, 0, 1, 'available', NOW(), NOW()),
('基于微服务的电商平台架构设计', '采用Spring Cloud微服务架构设计高可用、可扩展的电商平台', 4, '架构设计', 'engineering', 'teacher', '熟悉Spring Cloud和Docker容器化', '[1] 微服务架构设计模式 [2] Spring Cloud实战', 3, 0, 1, 'available', NOW(), NOW()),
('基于React Native的移动端应用开发', '使用React Native开发跨平台移动应用，实现iOS和Android双端运行', 3, '移动开发', 'engineering', 'teacher', '熟悉JavaScript和React框架', '[1] React Native官方文档 [2] 移动端开发最佳实践', 3, 0, 1, 'available', NOW(), NOW()),
('基于大数据的用户行为分析系统', '使用Hadoop和Spark对海量用户数据进行分析，挖掘用户行为模式', 4, '大数据', 'engineering', 'teacher', '熟悉Hadoop生态系统和Spark计算框架', '[1] Hadoop权威指南 [2] Spark快速大数据分析', 3, 0, 1, 'available', NOW(), NOW()),
('基于物联网的智能家居控制系统', '设计并实现基于物联网技术的智能家居控制中心，支持远程控制和自动化场景', 3, '物联网', 'engineering', 'teacher', '了解物联网协议和传感器技术', '[1] 物联网技术基础 [2] 智能家居系统设计', 3, 0, 1, 'available', NOW(), NOW()),
('基于自然语言处理的智能客服系统', '研究NLP技术在客服领域的应用，实现自动问答和意图识别功能', 4, 'NLP研究', 'research', 'teacher', '熟悉机器学习和自然语言处理算法', '[1] 自然语言处理综述 [2] 深度学习与NLP', 3, 0, 1, 'available', NOW(), NOW()),
