INSERT INTO `task_books` (`selection_id`, `content`, `deadline`, `version`, `requirements`, `tech_params`, `references`, `status`, `issuer_id`, `issued_at`, `confirm_by`, `confirm_at`, `rejector_id`, `reject_time`, `reject_comment`, `created_at`, `updated_at`) VALUES 
(1, '1. 完成系统需求分析和设计\n2. 开发前后端核心功能模块\n3. 进行系统集成测试\n4. 编写技术文档和用户手册\n5. 准备答辩材料', '2026-04-30', 1, '[{"id": 1, "text": "完成需求调研和分析"}, {"id": 2, "text": "设计系统架构和数据库"}, {"id": 3, "text": "实现核心功能模块"}, {"id": 4, "text": "编写测试用例并进行测试"}, {"id": 5, "text": "编写完整的技术文档"}]', '[{"name": "前端框架", "value": "Vue 3 + Element Plus", "note": "响应式UI框架"}, {"name": "后端框架", "value": "Spring Boot 2.7+", "note": "RESTful API"}, {"name": "数据库", "value": "MySQL 8.0", "note": "关系型数据库"}]', '[1] Vue.js官方文档\n[2] Spring Boot实战\n[3] 前端开发最佳实践', 'issued', 3, '2026-03-20 09:00:00', 8, '2026-03-20 10:00:00', 1, '2099-12-31 23:59:59', '', NOW(), NOW()),
(2, '1. 研究深度学习相关算法\n2. 构建图像识别模型\n3. 训练和优化模型参数\n4. 开发演示系统界面\n5. 撰写论文和技术报告', '2026-04-30', 1, '[{"id": 1, "text": "收集和整理数据集"}, {"id": 2, "text": "搭建深度学习训练环境"}, {"id": 3, "text": "实现CNN模型结构"}, {"id": 4, "text": "模型训练和参数调优"}, {"id": 5, "text": "开发可视化展示界面"}]', '[{"name": "深度学习框架", "value": "PyTorch 1.10+", "note": "GPU加速训练"}, {"name": "数据处理", "value": "OpenCV + NumPy", "note": "图像预处理"}]', '[1] 深度学习\n[2] PyTorch官方教程\n[3] 计算机视觉算法', 'issued', 3, '2026-03-20 09:30:00', 9, '2026-03-20 10:30:00', 1, '2099-12-31 23:59:59', '', NOW(), NOW()),
(3, '1. 学习区块链核心技术\n2. 设计智能合约逻辑\n3. 开发供应链管理系统\n4. 进行安全性测试\n5. 部署到测试网络', '2026-04-30', 1, '[{"id": 1, "text": "学习Solidity合约开发"}, {"id": 2, "text": "设计供应链数据结构"}, {"id": 3, "text": "实现链上数据存储"}, {"id": 4, "text": "开发Web3前端交互"}, {"id": 5, "text": "进行安全审计和测试"}]', '[{"name": "区块链平台", "value": "Ethereum", "note": "智能合约部署"}, {"name": "开发框架", "value": "Truffle + Hardhat", "note": "合约开发和测试"}]', '[1] 区块链技术指南\n[2] Solidity编程\n[3] 以太坊开发文档', 'issued', 3, '2026-03-20 10:00:00', 10, '2026-03-20 11:00:00', 1, '2099-12-31 23:59:59', '', NOW(), NOW()),
(4, '1. 学习微服务架构设计\n2. 使用Spring Cloud构建服务\n3. 实现服务注册和发现\n4. 配置网关和负载均衡\n5. 进行容器化部署', '2026-04-30', 1, '[{"id": 1, "text": "设计微服务拆分方案"}, {"id": 2, "text": "实现各服务模块"}, {"id": 3, "text": "配置服务治理组件"}, {"id": 4, "text": "实现API网关"}, {"id": 5, "text": "Docker容器化部署"}]', '[{"name": "微服务框架", "value": "Spring Cloud Alibaba", "note": "企业级解决方案"}, {"name": "容器化", "value": "Docker + K8s", "note": "容器编排管理"}]', '[1] 微服务架构设计\n[2] Spring Cloud实战\n[3] Docker容器技术', 'issued', 3, '2026-03-20 10:30:00', 11, '2026-03-20 11:30:00', 1, '2099-12-31 23:59:59', '', NOW(), NOW()),
(5, '1. 学习React Native框架\n2. 开发移动端应用界面\n3. 实现iOS和Android双端适配\n4. 集成原生模块功能\n5. 发布到应用商店', '2026-04-30', 1, '[{"id": 1, "text": "搭建RN开发环境"}, {"id": 2, "text": "设计移动端UI界面"}, {"id": 3, "text": "实现核心业务功能"}, {"id": 4, "text": "适配iOS和Android平台"}, {"id": 5, "text": "打包发布应用"}]', '[{"name": "移动框架", "value": "React Native 0.70+", "note": "跨平台开发"}, {"name": "状态管理", "value": "Redux Toolkit", "note": "全局状态管理"}]', '[1] React Native官方文档\n[2] 移动端开发实战\n[3] 跨平台应用设计', 'unissued', 3, '2099-12-31 23:59:59', 0, '2099-12-31 23:59:59', 1, '2099-12-31 23:59:59', '', NOW(), NOW());
