(0, 1, '关于2026届毕业设计选题通知', '各位同学请注意，2026届毕业设计选题将于3月1日正式开始，请及时登录系统选择题目。选题截止时间为3月15日。', 0, '2099-12-31 23:59:59', 'published', '2026-02-25 09:00:00', '', 0, 'high', 'business', NOW()),
(0, 1, '中期检查时间安排通知', '2026届毕业设计中期检查将在4月15日-4月30日期间进行，请各位同学按时提交中期报告。', 0, '2099-12-31 23:59:59', 'published', '2026-04-01 10:00:00', '', 0, 'high', 'business', NOW()),
(0, 1, '答辩安排通知', '2026届毕业设计答辩将于6月1日-6月10日期间举行，具体时间和地点另行通知。', 0, '2099-12-31 23:59:59', 'published', '2026-05-20 14:00:00', '', 0, 'urgent', 'business', NOW()),
(8, 3, '您的选题已通过审核', '您选择的《基于Vue3的在线教育平台设计与实现》题目已通过导师审核，请尽快联系导师领取任务书。', 0, '2099-12-31 23:59:59', 'published', '2026-03-15 10:30:00', 'selection', 1, 'normal', 'business', NOW()),
